hd('5. ගණිතමය සහ භෞතික සූත්‍ර')
hd('5.1 ජල ගිල්වීම සහ ආසන්න Draught',2)
formula('(F1)','T ≈ m / (ρw · Cb · L · B)','මෙහි T = draught (m), m = displacement mass (kg), Cb = assumed block coefficient, L = hull length, B = beam. මෙය Archimedes මූලධර්මයෙන් ගත් සරල සමානුපාතික ආකෘතියකි. නිශ්චිත hydrostatic curve එකක් නොමැති නිසා survey එකක් ලෙස භාවිත කළ නොහැක.')
hd('5.2 Hull wetted surface area',2)
formula('(F2)','S ≈ L · (B + 2T) · kwet','S = ජලයට ස්පර්ශ වන ආසන්න පෘෂ්ඨය (m²), kwet = 0.70–0.86 අතර assumed geometry multiplier. මෙය measured wetted area එකක් නොවේ. Hull CAD හෝ towing tests වලින් තහවුරු කළ යුතුය.')
hd('5.3 Reynolds Number සහ ITTC-1957',2)
formula('(F3)','Re = U · L / ν','U = speed through water (m/s), L = යාත්‍රාවේ දිග, ν = ජලයේ kinematic viscosity. Reynolds Number dimensionless වේ.')
formula('(F4)','Cf = 0.075 / (log10(Re) − 2)²','ITTC-1957 model–ship correlation line එකෙන් ලැබෙන friction coefficient එක. මෙය cited standard relationship එකකි. [S1]')
formula('(F5)','Rf = 0.5 · ρw · U² · S · Cf · (1+k)','Rf = frictional hull resistance (N). k = 0–0.14 අතර uncalibrated form parameter. ITTC-57 හි form corrections සම්බන්ධ convention නිසා මෙම අතිරේක multiplier double counting විය හැකිදැයි actual hull tests වලින් බැලිය යුතුය.')
hd('5.4 Froude Number හා residual hull drag',2)
formula('(F6)','Fr = U / √(gL)','Fr dimensionless වේ; wave-making behavior සඳහා speed-to-length indicator එකකි.')
formula('(F7)','Rres = mg · 0.018 · (Fr/0.38)^4 · (Cb/0.47)^0.55','මේ expression එක external empirical hull design law එකක් ලෙස උපුටා නොගත යුතුය. Dataset එකේ power-speed trend එකට shape ලබාදීම සඳහා තෝරාගත් heuristic parametric relationship එකකි; සියලු coefficients යාත්‍රාවකට අනුව calibration අවශ්‍යය.')
hd('5.5 තරංග හා වායු බලපෑම',2)
formula('(F8)','λ ≈ gTp²/(2π); wave steepness = Hs/λ','Deep-water linear-wave dispersion approximation. Tp = peak wave period (s), Hs = significant wave height (m). NOAA අනුව Hs යනු ඉහළම තුනෙන් එකක සාමාන්‍ය තරංග උසයි; එක් එක් තරංගය Hs සීමාවෙන් කුඩා විය යුතු නැත. [S3]')
formula('(F9)','Rwave = 0.5ρwU²S · 0.42 · (Hs/L)² · E(heading) · (1+2Hs/λ)','Rwave යනු පර්යේෂණය සඳහාම නිර්මාණය කළ phenomenological wave-added-resistance proxy එකකි. E(heading) = 0.65 + 0.375(1+cos θ) ලෙස synthetic wave incidence එකෙන් ගණනය කෙරේ. නියම seakeeping solution එකක් නොවේ.')
formula('(F10)','Rair = 0.5ρaCdA(U+Uheadwind)²','Cd=1.05, A = above-water projected area approximation. Wind direction හා speed synthetic; headwind/relative-air velocity convention ඉතා සරල කර ඇත.')
formula('(F11)','Rtotal = Rf + Rres + Rwave + Rair','එක් එක් component N ඒකකයෙන් එකතු වේ. Rtotal සම්පූර්ණ vessel performance එක මනින towing-tank estimate එකක් නොවේ.')
hd('5.6 Power, fuel mass සහ fuel volume',2)
formula('(F12)','Pe(kW) = Rtotal(N) · U(m/s) / 1000','Effective power = resistance force × speed through water. මෙය mechanics energy relation එකකි.')
formula('(F13)','Pb(kW) = Pe / ηD','ηD = assumed propulsive efficiency (0.46–0.67). ηD measured propulsion system efficiency එකක් නොවේ.')
formula('(F14)','Fuel_leg(L) = Pb(kW) · t(h) · BSFC(kg/kWh) / ρf(kg/L)','Engine brake power, duration, specific fuel consumption සහ density සම්බන්ධ energy–mass conversion. FAO fuel consumption approach එකට අනුකූල ඓකක සම්බන්ධතාවයකි. [S2]')
formula('(F15)','Fuel_trip = Fuel_out + Fuel_return + Fuel_fishing_operations','Fishing operation term එක engine duty × load × hours හා auxiliary power සඳහා assumed BSFC උපයෝගී කරගනී. Actual engine duty, generator operation, fishing gear සහ catch loading profiles ලබාගත් විට පමණක් calibrate කළ හැක.')
hd('5.7 Research-only uncertainty සහ reserve scenario',2)
formula('(F16)','Sensitivity_lower = Fuel_trip(1−u); upper = Fuel_trip(1+1.3u)','u යනු scenario uncertainty factor එකක් පමණි (sea-state severity හා engine age මත අගය වැඩි වේ). 10%-90% calibrated interval ලෙස වැරදි ලෙස හඳුන්වන්න එපා. Column names වල “low/high” ලෙස තබා ඇත.')
formula('(F17)','Simulated_total = Fuel_trip + Fuel_trip · reserve_fraction','reserve_fraction = 0.20–0.35 අතර සිමියුලේෂන් parameter එකකි; ආරක්ෂිත/නීතිමය අවම ඉන්ධන ප්‍රමාණයක් හෝ ගමනකට භාවිත කළ යුතු නිර්දේශයක් නොවේ.')

hd('6. Physics constraints හා Model-ready data')
para('පෙර ගණනය කළ synthetic fuel total එක regression target ලෙස භාවිත කළත් එය real ground truth නොවන නිසා “model learns a simulator” ප්‍රතිඵලයක් පමණක් පෙන්වයි. Standard PINN එකක් සඳහා governing equations වල PDE-residual differentiability/physics-informed losses අවශ්‍ය වන අතර මෙහි data-driven simulator constraints පමණක් තිබේ. ඉදිරි prototype එක Hybrid Physics-Guided Neural Network ලෙසත් තවත් කොටසක genuine physics residual implement කළහොත් පමණක් PINN ලෙසත් වෙන් කළ යුතුය.')
para('ඉදිරි model objective එකේ උදාහරණයක්: L = MSE(y_pred,y_measured) + λ1 MSE(Pe − Rtotal·U/1000) + λ2 MSE(Pb·ηD−Pe) + λ3 · penalty(y_pred<0). Measured data ලැබෙන තුරු පළමු term සඳහා `y_simulated` භාවිත කරන්නේ simulator imitation එකකටයි; real-world fit එකට නොවේ.')
para('Model-ready NPZ හි pre-trip features 20ක්, target fuel_consumption_l_model, vessel-grouped train/validation/test splits සහ train-only feature scaling parameters ඇත. Leakage වළක්වන්නේ එකම vessel_id එක splits කිහිපයක නොපැමිණීම සහ derived target variables feature inputs ලෙස නොදීමෙනි.')

hd('7. Dataset එකෙන් ගත් Worked Example')
e=master[0];l=[x for x in legs if x['scenario_id']==e['scenario_id']];one=next(x for x in l if x['direction']=='outbound')
table(['පරාමිතිය','Dataset row හි අගය'],[['Scenario / C1 trip',e['scenario_id']+' / '+e['c1_trip_id']],['Vessel class / id',e['vessel_type']+' / '+e['vessel_id']],['Displacement mass (kg)',e['displacement_mass_kg']],['Length × Beam (m)',e['vessel_length_m']+' × '+e['vessel_beam_m']],['Loaded draft T (m)',e['loaded_draft_m_approx']],['Weather Hs / Tp',e['forecast_wave_hs_m_c1_synthetic']+' m / '+e['wave_peak_period_s_c1_synthetic']+' s'],['Outward leg total R (N)',one['total_resistance_n']],['Outward leg effective power (kW)',one['effective_power_kw']],['Outward leg brake power (kW)',one['brake_power_kw']],['Outward leg time (h)',one['travel_time_h']],['Outward leg fuel (L)',one['leg_fuel_l']],['Total transit fuel (L)',e['transit_fuel_l_model']],['Fishing operations fuel (L)',e['fishing_fuel_l_model']],['Total simulated fuel (L)',e['fuel_consumption_l_model']]])
formula('Example check A:',f"Fuel_out ≈ {float(one['brake_power_kw']):.4f} × {float(one['travel_time_h']):.4f} × {float(one['bsfc_kg_per_kwh']):.5f} / 0.84 = {float(one['leg_fuel_l']):.4f} L",'Rounded CSV fields වලින් නැවත ගණනය කිරීමේදී සුළු rounding වෙනස්කම් සිදුවේ.')
formula('Example check B:',f"Fuel_total ≈ {float(e['transit_fuel_l_model']):.4f} + {float(e['fishing_fuel_l_model']):.4f} = {float(e['fuel_consumption_l_model']):.4f} L",'මෙය අභ්‍යන්තර arithmetic consistency example එකක් පමණි; මිනුම් කළ fuel consumption නොවේ.')

hd('8. සංඛ්‍යානමය බෙදාහැරීම සහ පරීක්ෂණ')
for vt in ['OFRP','IDAY','IMUL']:
 vals=by[vt];para(f'{vt}: records {len(vals):,}; simulated fuel median {np.median(vals):.2f} L; range {np.min(vals):.2f}–{np.max(vals):.2f} L.')
